 // agree. The concrete returned error also unwraps to the original cause.
 var ErrPoisoned = errors.New("audit chain poisoned")

-// ErrPersistenceInProgress is returned by immediate append APIs when an
-// AppendPersist callback attempts to re-enter the same chain. Waiting here
-// would deadlock because the callback owns the exclusive reservation.
-var ErrPersistenceInProgress = errors.New("audit persistence callback in progress")
