 	if r.chain == nil {
 		return
 	}
@@ -172,11 +179,21 @@ func (r *Reconciler) recordHaltAuditEvent(divergence, chainBalance, bookBalance
 		"chain_balance_usd": chainBalance,
 		"book_balance_usd":  bookBalance,
 	}
-	if _, err := r.chain.Append(string(store.EventError), payload); err != nil {
-		log.Printf("[RECONCILE] failed to append audit event: %v", err)
+	auditID := ulid.MustNew(ulid.Timestamp(time.Now().UTC()), ulidEntropy()).String()
+	if _, err := r.chain.AppendPersistContext(ctx, string(store.EventError), payload, func(ev audit.Event) error {
+		_, err := r.db.RecordEvent(ctx, store.AuditEvent{ID: auditID, OccurredAt: ev.Timestamp,
+			EventKind: store.EventError, Detail: string(ev.Payload), Includee: ev.Includee})
+		return err
+	}); err != nil {
+		log.Printf("[RECONCILE] failed to persist halt audit event: %v", err)
 	}
 }

