+// TestReconcileHalt_PersistedWithChainLinkage is the regression lock for the
+// review MAJOR: halt events must go through the persisted HMAC-chained path,
+// so a halt interleaved between two persisted events keeps the next row's
+// includee lineage intact instead of forking from an unpersisted predecessor.
+func TestReconcileHalt_PersistedWithChainLinkage(t *testing.T) {
+	ctx := context.Background()
+	st, err := store.Open(ctx, t.TempDir()+"/test.db")
+	if err != nil {
+		t.Fatalf("Open: %v", err)
+	}
+	defer st.Close()
+
+	chain := audit.NewChain("", "")
+	_, err = chain.AppendPersistContext(ctx, "test_seed", map[string]any{"k": "v"}, func(ev audit.Event) error {
+		_, err := st.RecordEvent(ctx, store.AuditEvent{ID: "seed-1", OccurredAt: ev.Timestamp,
+			EventKind: store.EventKind("test_seed"), Detail: string(ev.Payload), Includee: ev.Includee})
+		return err
+	})
+	if err != nil {
+		t.Fatalf("seed AppendPersistContext: %v", err)
+	}
+
+	initial := 220.0
+	fetcher := NewMockChainBalanceFetcher(initial, 5.0) // $5 drift > $1 delta
+	r := NewReconcilerWithChain(st, chain, fetcher, 1.0, initial)
+
+	if err := r.Reconcile(ctx, "cbBTC/USDC", 65000.0); err == nil {
+		t.Fatalf("expected halt for divergence > delta, got nil")
+	}
+
+	events, err := st.AllEvents(ctx)
+	if err != nil {
+		t.Fatalf("AllEvents: %v", err)
+	}
+	if len(events) != 2 {
+		t.Fatalf("expected seed + halt rows, got %d", len(events))
+	}
+	halt := events[1]
+	if halt.EventKind != store.EventError {
+		t.Errorf("expected halt kind %q, got %q", store.EventError, halt.EventKind)
+	}
+	chainEvents := chain.Events()
+	chainHalt := chainEvents[len(chainEvents)-1]
+	if halt.Includee != chainHalt.Includee {
+		t.Errorf("halt row includee %q does not match chained event includee %q",
+			halt.Includee, chainHalt.Includee)
+	}
+	if halt.Includee == "" {
+		t.Errorf("halt row has empty includee — lineage forked")
+	}
+	if err := chain.Verify(); err != nil {
+		t.Errorf("chain Verify after halt: %v", err)
+	}
+}

